// Embedded fonts for the brief PDF renderer (src/lib/pdf.ts).
//
// Both faces are OFL-licensed Google Fonts, downloaded from Google Fonts and
// subset to Latin-1 (U+0020-007E, U+00A0-00FF, bullet U+2022) with pyftsubset —
// sanitizeForPdf in report-delivery.ts strips everything outside that range
// before rendering, so nothing is lost.
//
// - Archivo Black (display: title + section chips) ~40KB
// - Inter Regular / Inter Bold (body)              ~30KB each
//
// Kept in a separate module so pdf.ts stays readable.

/** Archivo Black Regular, base64 TTF. */
export const ARCHIVO_BLACK_TTF =
  "";

/** Inter Regular, base64 TTF. */
export const INTER_REGULAR_TTF =
  "";

/** Inter Bold, base64 TTF. */
export const INTER_BOLD_TTF =
  "";
